import{_ as i,o as e,c as a,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Orchestrator Meeting 2021-11-30","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2021-11-30","date":"2021-11-30T00:00:00.000Z","updated":"2021-12-01T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH算法","高可用性","可伸缩性","对象存储","块存储","文件系统存储","一致性","去中心化","性能","Bluestore","Bluefs","Rocksdb","OSD","MON","MDS","PG","RADOS","librados","libcephfs","cephfs","rbd","radosgw","RGW","RESTful API","认证","授权","加密","损坏码","复制","快照","克隆","薄分配","iSCSI","Fibre Channel","NFS","CIFS","POSIX","监控","仪表板","管理","编排","自动化","集成","容器化","Kubernetes","Docker","虚拟化","云计算","AWS","Azure","Google Cloud","混合云","多云","存储集群","节点","磁盘","SSD","HDD","JBOD","SAN","NAS","网络","拓扑","故障域","恢复","弹性","负载均衡","缓存","压缩","去重","分级","性能调优","基准测试","测试","验证"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Orchestrator_Meeting_2021-11-30.md","filePath":"posts/2021/Ceph_Orchestrator_Meeting_2021-11-30.md","lastUpdated":1780459816000}'),o={name:"posts/2021/Ceph_Orchestrator_Meeting_2021-11-30.md"};function r(s,l,n,h,p,u){return e(),a("div",null,[...l[0]||(l[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概要" tabindex="-1">会议概要 <a class="header-anchor" href="#会议概要" aria-label="Permalink to &quot;会议概要&quot;">​</a></h4><ul><li><strong>日期</strong>: 2021-11-30</li><li><strong>主持人</strong>: [主持人姓名]</li><li><strong>参会人员</strong>: [参会人员列表]</li><li><strong>主要议题</strong>: <ol><li>集群状态更新</li><li>Topo LVM 状态更新</li><li>放置规范（Placement Spec）的使用问题</li><li>长期架构改进讨论</li><li>HFNFS 相关问题</li></ol></li></ul><h4 id="讨论内容" tabindex="-1">讨论内容 <a class="header-anchor" href="#讨论内容" aria-label="Permalink to &quot;讨论内容&quot;">​</a></h4><ol><li><p><strong>集群状态更新</strong></p><ul><li>集群目前存在锁定问题，正在尝试修复。</li><li>正在进行一些更改以减少代理报告的工作量，并增加日志记录以监控代理与管理器的响应时间。</li><li>集群状态良好，计划向其他组件开放访问，但不包括 Rook。</li></ul></li><li><p><strong>Topo LVM 状态更新</strong></p><ul><li>Topo LVM 的设计更改（包括原始设备而不仅仅是 LVs）目前停滞。</li><li>正在为 ODF 开发一个独立的解决方案，使用 Topo LVM Operator。</li><li>由于长期愿景的分歧，决定创建一个新的 Operator 来驱动 Topo LVM。</li><li>该项目正在进行中，目标是将其纳入 Top LVM 项目。</li></ul></li><li><p><strong>放置规范（Placement Spec）的使用问题</strong></p><ul><li>讨论了放置规范在不同场景下的使用问题，特别是混合使用导致的不一致性。</li><li>需要决定是否分离数据结构或继续当前的使用方式。</li></ul></li><li><p><strong>长期架构改进讨论</strong></p><ul><li>讨论了在大规模测试和性能验证方面的长期愿景。</li><li>需要建立一个长期的工作列表，特别是在大规模集群管理和调度方面。</li><li>提出了在 Totality 中增加更多功能以支持大规模测试的建议。</li></ul></li><li><p><strong>HFNFS 相关问题</strong></p><ul><li>讨论了 HFNFS 的使用案例和触发条件。</li><li>需要实现主机离线情况的处理，并确保服务在节点离线后能够正确恢复。</li><li>需要进一步研究 Kubernetes 中的 NFS 故障转移行为。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>继续监控和修复集群的锁定问题。</li><li>推进 Topo LVM Operator 的开发，并寻求将其纳入 Top LVM 项目。</li><li>对放置规范的使用问题进行进一步讨论和决策。</li><li>开始制定长期架构改进的工作列表。</li><li>研究并实现 HFNFS 的故障转移机制。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续监控集群状态并实施必要的修复。</li><li>完成 Topo LVM Operator 的开发，并提交给 Top LVM 项目。</li><li>安排进一步讨论放置规范的使用问题。</li><li>制定并开始实施长期架构改进的工作列表。</li><li>研究 HFNFS 的故障转移机制，并与 Sage 进一步讨论相关细节。</li></ul><h4 id="其他事项" tabindex="-1">其他事项 <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项&quot;">​</a></h4><ul><li>感谢 Daniel 在 Red Hat 的工作和贡献，Daniel 即将离职。</li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><ul><li>会议在感谢和告别中结束。</li></ul>',13)])])}const _=i(o,[["render",r]]);export{c as __pageData,_ as default};
